/**
 * Shape of the content bundle generated by `radiocorpus export-learning`
 * (src/radiocorpus/learning/content.py). The JSON is the single source of
 * truth; these types only describe it.
 */

export type CodeSystem = "TEN_CODE" | "ELEVEN_CODE" | "CHP_CARD_ALPHABET";
export type ItemKind = "code" | "letter";

export interface HumanReview {
  reviewer: string;
  reviewed_at: string;
  decision: "ACCEPT" | "REJECT" | "CORRECT";
  notes: string;
}

export type HumanReviewState = "none" | "accepted" | "corrected" | "rejected" | "disputed";

export interface Review {
  method: string;
  reviewer: string;
  reviewer_is_human: boolean;
  reviewed_at: string;
  inspection: string | null;
  finding: string;
  human: HumanReview[];
}

export interface ItemStatus {
  source_matched: boolean;
  human_verified: boolean;
  human_review: HumanReviewState;
  answer_basis: "automated_review" | "human_reading";
  eligibility: string;
  currentness: string;
  learner_safe: boolean;
}

export interface LearningItem {
  id: string;
  kind: ItemKind;
  code_system: CodeSystem;
  term: string;
  answer: string;
  locator: string;
  page: number | null;
  locator_kind: string;
  excerpt: string;
  source_id: string;
  review: Review;
  status: ItemStatus;
  limitations: string[];
  notes: string[];
}

export interface ExcludedEntry {
  fact_id: string;
  kind: ItemKind;
  term: string;
  code_system: string | null;
  label: string;
  failure_class: string;
  reason: string;
  locator: string;
  page: number | null;
  /** Raw extraction text for reviewers. Never shown to learners as this entry's meaning. */
  excerpt: string;
  human: HumanReview[];
  human_review: HumanReviewState;
}

export interface Lesson {
  id: string;
  title: string;
  summary: string;
  title_ko: string;
  summary_ko: string;
  item_ids: string[];
}

export interface Source {
  source_id: string;
  title: string;
  title_basis: string;
  issuing_agency: string;
  jurisdiction: string;
  version: string;
  version_basis: string;
  url: string;
  sha256: string;
  byte_length: number;
  page_count: number;
  retrieved_at: string;
  currentness: string;
  source_quality: string;
  document_in_repository: boolean;
  document_note: string;
  human_source_review: {
    printed_revision: string | null;
    listed_at_url: string | null;
    listed_checked_at: string | null;
    reviewer: string;
    reviewed_at: string;
    notes: string;
  } | null;
}

export interface Jurisdiction {
  id: string;
  name: string;
  short_name: string;
  region: string;
  agency_id: string;
}

export interface ContentBundle {
  content_version: string;
  schema_version: number;
  jurisdiction: Jurisdiction;
  source: Source;
  counts: {
    reviewed: number;
    teachable: number;
    teachable_codes: number;
    teachable_letters: number;
    excluded: number;
    human_verified: number;
    human_corrected: number;
    human_rejected: number;
    human_disputed: number;
    human_reviewers: number;
  };
  generated_from: string[];
  lessons: Lesson[];
  items: LearningItem[];
  excluded: ExcludedEntry[];
}
